  if (mod === '../image') return mockImage;
  if (mod === '../topics') return mockTopics;
  if (mod === '../file') return mockFile;
  if (mod === 'validator') return mockValidator;
  if (mod === 'mime') return mockMime;
  return originalRequire.apply(this, args);
};

// Load the uploads module
