require('/app/src/posts/uploads.js')(posts);

async function runTests() {
  console.log('Running validation tests...');

  // Reset tracking
  deletedFiles = [];

  // Test 1: Invalid input
  try {
    await posts.uploads.deleteFromDisk(null);
    assert.fail('Should have thrown error');
  } catch (err) {
    assert.strictEqual(err.message, 'Invalid input: filePaths must be a string or an array of strings');
