  await posts.uploads.deleteFromDisk(['valid.txt', 123, null, undefined, false]);
  assert.strictEqual(deletedFiles.length, 1);
  assert.strictEqual(deletedFiles[0].endsWith('valid.txt'), true);
  console.log('✓ Non-string array items ignored');

  console.log('\nAll validation tests passed!');
